package io.github.neoruaa.glasmio.core

import androidx.compose.foundation.shape.CornerBasedShape
import androidx.compose.foundation.shape.CornerSize
import androidx.compose.runtime.Immutable
import androidx.compose.ui.geometry.Size
import androidx.compose.ui.graphics.Outline
import androidx.compose.ui.unit.Density
import androidx.compose.ui.unit.Dp
import androidx.compose.ui.unit.LayoutDirection
import androidx.compose.ui.unit.dp
import com.kyant.shapes.UnevenRoundedRectangle

/** Material's CornerBasedShape contract, with outlines generated by Kyant0/Shapes. */
@Immutable
class G2RoundedRectangle(
    topStart:CornerSize, topEnd:CornerSize, bottomEnd:CornerSize, bottomStart:CornerSize,
):CornerBasedShape(topStart,topEnd,bottomEnd,bottomStart) {
    constructor(radius:Dp):this(CornerSize(radius),CornerSize(radius),CornerSize(radius),CornerSize(radius))
    constructor(percent:Int):this(CornerSize(percent),CornerSize(percent),CornerSize(percent),CornerSize(percent))
    constructor(topStart:Dp,topEnd:Dp,bottomEnd:Dp,bottomStart:Dp):this(CornerSize(topStart),CornerSize(topEnd),CornerSize(bottomEnd),CornerSize(bottomStart))

    private data class OutlineKey(val size:Size,val a:Float,val b:Float,val c:Float,val d:Float,val direction:LayoutDirection)
    private val outlines=LinkedHashMap<OutlineKey,Outline>(32,.75f,true)

    override fun createOutline(size:Size,topStart:Float,topEnd:Float,bottomEnd:Float,bottomStart:Float,layoutDirection:LayoutDirection):Outline {
        val key=OutlineKey(size,topStart,topEnd,bottomEnd,bottomStart,layoutDirection)
        // Reuse the path identity for recurring card sizes, so Skia can retain its
        // tessellation/mask across pager pages. Outlines are read-only after creation.
        return synchronized(outlines) {
            outlines[key] ?: UnevenRoundedRectangle(topStart.dp,topEnd.dp,bottomEnd.dp,bottomStart.dp)
                .createOutline(size,layoutDirection,Density(1f)).also {
                    if(outlines.size>=32)outlines.remove(outlines.keys.first())
                    outlines[key]=it
                }
        }
    }

    override fun copy(topStart:CornerSize,topEnd:CornerSize,bottomEnd:CornerSize,bottomStart:CornerSize):CornerBasedShape =
        G2RoundedRectangle(topStart,topEnd,bottomEnd,bottomStart)

    override fun equals(other:Any?)=other is G2RoundedRectangle&&topStart==other.topStart&&topEnd==other.topEnd&&bottomEnd==other.bottomEnd&&bottomStart==other.bottomStart
    override fun hashCode()=31*(31*(31*topStart.hashCode()+topEnd.hashCode())+bottomEnd.hashCode())+bottomStart.hashCode()
}
